{"steps":[{"step_id":1,"time":"","role":"市气象局","action":"灾害预警","description":"气象部门率先发布强降雨预警信息，通过地质灾害气象预报预警体系研判滑坡灾害气象风险等级，向相关部门及社会公众发布预警信息，提醒做好地质灾害防范准备。","resources":[]},{"step_id":2,"time":"","role":"气象/监测组","action":"险情监测","description":"自然资源部门借助专业监测设备以及群测群防员，对灾害隐患点展开实时严密监测，密切关注滑坡体变形迹象，一旦发现灾害迹象立即按程序上报。","resources":[{"resource_type":"无人机","quantity":1},{"resource_type":"环境监测设备","quantity":1}]},{"step_id":3,"time":"","role":"社区/基层","action":"险情巡查","description":"村干部、群测群防员和监测员对地质灾害隐患点开展巡查，发现险情加剧或出现滑坡前兆时，立即通过敲锣、广播等方式发出撤离信号，组织受威胁群众按预定安全撤离路线有序转移。","resources":[]},{"step_id":4,"time":"","role":"社区/基层","action":"灾情上报","description":"社区/村级组织在发现滑坡险情后，立即将地质灾害发生时间、地点、类型、灾害体规模、等级、伤亡人数、直接经济损失、可能的引发因素、发展趋势以及先期处置情况等速报内容向上级政府及有关部门报告。","resources":[]},{"step_id":5,"time":"","role":"市应急局","action":"会商研判","description":"市应急局和市资源规划局接到地质灾害报告后，相互通报信息并开展会商，对灾情进行核实。按相关规定向省自然资源厅、省应急厅、市委市政府报告，及时做好续报和终报工作。","resources":[]},{"step_id":6,"time":"","role":"应急指挥部","action":"启动响应","description":"西安市政府立即启动《西安市突发地质灾害应急预案》Ⅱ级响应，成立市突发地质灾害应急指挥部和现场指挥部，命令市防灾减灾救灾工作委员会各成员单位按照预案职责指导蓝田县开展人员疏散安置、应急救援、交通疏导、警戒防控等工作。","resources":[]},{"step_id":7,"time":"","role":"应急指挥部","action":"应急队伍集结","description":"市突发地质灾害应急指挥部命令各成员单位、各工作组迅速就位，明确各自职责，调集各类应急装备和救援队伍赶赴灾害现场集结，有条不紊地组织协调各部门开展应急处置工作。","resources":[{"resource_type":"消防车","quantity":2},{"resource_type":"运输车辆","quantity":4},{"resource_type":"挖掘机","quantity":2},{"resource_type":"吊装设备","quantity":1}]},{"step_id":8,"time":"","role":"市资源规划局","action":"危险区排查","description":"市资源规划局会同社区/基层对滑坡影响范围开展危险区排查，划定危险区范围，设立警示标志，明确威胁区域边界，为人员转移和现场管控提供依据。","resources":[{"resource_type":"无人机","quantity":1}]},{"step_id":9,"time":"","role":"区政府","action":"危险区划定","description":"区政府根据地质灾害排查结果，划定危险区范围，设立警示标志，封锁进出道路，禁止无关人员进入危险区域。","resources":[]},{"step_id":10,"time":"","role":"社区/基层","action":"人员转移","description":"村干部、监测员带领志愿者，通过敲锣发出撤离信号和广播通知受威胁群众，按照预定的安全撤离路线，引导大家有序转移到安全区域。在转移过程中，特别安排专人照顾老弱病残孕等特殊人群，确保每个人的安全。","resources":[]},{"step_id":11,"time":"","role":"疏散引导组","action":"人员转移","description":"疏散引导组组织受滑坡威胁群众按照预定安全撤离路线有序转移到安全区域，逐户排查确保无人员遗漏，做好转移人员登记和去向追踪。","resources":[{"resource_type":"运输车辆","quantity":3}]},{"step_id":12,"time":"","role":"后勤保障和善后安置组","action":"安置点开放","description":"乡镇政府在安全区域设置临时安置点，开放安置场所，做好安置和生活保障工作，登记群众信息，并发放食品、饮用水等生活物资，确保转移群众基本生活需求得到满足。","resources":[{"resource_type":"帐篷","quantity":30},{"resource_type":"发电机","quantity":2}]},{"step_id":13,"time":"","role":"后勤保障和善后安置组","action":"安置救助","description":"后勤保障和善后安置组根据现场应急工作需要，做好救灾物资及应急车辆等后勤保障工作，及时发放食品、饮用水、被褥等生活物资，保障受灾群众基本生活。","resources":[{"resource_type":"帐篷","quantity":20},{"resource_type":"急救包","quantity":10}]},{"step_id":14,"time":"","role":"交通管制组","action":"交通管制","description":"警戒防控组对受灾区域的道路入口实施临时交通管制措施，严禁无关车辆及人员进入，保障救援通道畅通。","resources":[]},{"step_id":15,"time":"","role":"交通管制组","action":"救援引导","description":"交通管制组引导救援车辆和人员有序进入灾害现场，保障应急救援力量快速通行。","resources":[]},{"step_id":16,"time":"","role":"现场指挥部","action":"安全确认","description":"现场指挥部组织专业人员对滑坡体及周边区域进行安全评估，确认救援作业区域安全条件，在确保救援人员安全的情况下方可开展搜救作业。","resources":[{"resource_type":"生命探测仪","quantity":1},{"resource_type":"无人机","quantity":1}]},{"step_id":17,"time":"","role":"消防救援组","action":"救援搜救","description":"专业处置组调集各类应急装备开展灾情侦查，组织应急救援队伍携带生命探测仪、破拆工具等装备，对滑坡区域失联人员进行全力搜救，有序开展应急救灾工作。","resources":[{"resource_type":"生命探测仪","quantity":2},{"resource_type":"破拆工具","quantity":2},{"resource_type":"消防车","quantity":1}]},{"step_id":18,"time":"","role":"市消防救援支队","action":"人员搜救","description":"市消防救援支队持续开展人员搜救工作，对重点区域进行反复搜索，利用生命探测仪等专业设备全力搜寻失联人员。","resources":[{"resource_type":"生命探测仪","quantity":1},{"resource_type":"破拆工具","quantity":2}]},{"step_id":19,"time":"","role":"医疗救护组","action":"医疗救护","description":"医疗卫生组迅速将因灾受伤人员送至临时医疗点，实施现场救治，对伤员进行伤情评估和紧急处理。","resources":[{"resource_type":"救护车","quantity":2},{"resource_type":"急救包","quantity":5}]},{"step_id":20,"time":"","role":"医疗救护组","action":"伤员转运","description":"医疗救护组对伤情较重人员及时转运至后方医院进行进一步救治，确保伤员得到有效医疗救治。","resources":[{"resource_type":"救护车","quantity":2}]},{"step_id":21,"time":"","role":"医疗救护组","action":"心理援助","description":"医疗救护组对受灾群众和救援人员开展心理援助，提供心理疏导和干预服务，缓解灾害带来的心理创伤。","resources":[]},{"step_id":22,"time":"","role":"调查评估组","action":"隐患监测","description":"调查监测组制定监测方案，明确监测方法，对灾情发展趋势进行预测及监测，密切关注滑坡体变化，防止次生灾害发生。","resources":[{"resource_type":"无人机","quantity":1},{"resource_type":"环境监测设备","quantity":1}]},{"step_id":23,"time":"","role":"气象/监测组","action":"险情监测","description":"气象部门持续开展气象监测，密切关注降雨趋势，为地质灾害应急处置提供气象服务保障。","resources":[]},{"step_id":24,"time":"","role":"后勤保障和善后安置组","action":"物资供应","description":"后勤保障组根据现场应急工作需要，持续做好救灾物资供应，确保帐篷、食品、饮用水、急救包等物资及时到位。","resources":[{"resource_type":"帐篷","quantity":20},{"resource_type":"急救包","quantity":10},{"resource_type":"发电机","quantity":1}]},{"step_id":25,"time":"","role":"综合协调组","action":"通信保障","description":"综合协调组组织通信保障力量，确保灾害现场通信畅通，必要时启用卫星电话等应急通信设备。","resources":[{"resource_type":"卫星电话","quantity":3}]},{"step_id":26,"time":"","role":"国网厦门供电公司","action":"电力保障","description":"供电公司做好应急供电保障工作，确保现场指挥部、临时医疗点和安置点电力供应。","resources":[{"resource_type":"发电机","quantity":2}]},{"step_id":27,"time":"","role":"工程抢险组","action":"现场处置","description":"工程抢险组组织力量对滑坡体进行现场处置，清理滑坡堆积体，加固不稳定斜坡，抢修受损基础设施，防止次生灾害发生。","resources":[{"resource_type":"挖掘机","quantity":2},{"resource_type":"吊装设备","quantity":1}]},{"step_id":28,"time":"","role":"市资源规划局","action":"地灾调查","description":"市资源规划局组织开展地质灾害调查，查明滑坡规模、成因、发展趋势，为后续处置和恢复重建提供技术依据。","resources":[{"resource_type":"无人机","quantity":1},{"resource_type":"环境监测设备","quantity":1}]},{"step_id":29,"time":"","role":"调查评估组","action":"处置方案","description":"调查评估组根据地质灾害调查结果，制定滑坡应急处置方案，明确处置措施、责任分工和完成时限。","resources":[]},{"step_id":30,"time":"","role":"后勤保障和善后安置组","action":"灾情统计","description":"市应急局会同相关部门做好灾情统计工作，核实伤亡人数、直接经济损失、受灾范围等信息，及时向上级报告。","resources":[]},{"step_id":31,"time":"","role":"应急指挥部","action":"搜救完成","description":"在各工作组通力合作下，失联人员已全部找到，现场再无次生灾害发生，搜救工作完成。","resources":[]},{"step_id":32,"time":"","role":"市委宣传部","action":"信息通报","description":"市委宣传部按照相关规定及时做好信息发布工作，向社会通报灾情和救援进展情况，回应社会关切。","resources":[]},{"step_id":33,"time":"","role":"市委宣传部","action":"舆情管控","description":"市委宣传部和市委网信办加强舆情监测和管控，及时引导舆论，防止不实信息传播。","resources":[]},{"step_id":34,"time":"","role":"交通管制组","action":"秩序恢复","description":"交通管制组和市公安局做好受灾区域治安交通秩序恢复工作，解除临时交通管制措施，恢复道路通行。","resources":[]},{"step_id":35,"time":"","role":"市市政园林局","action":"生态修复","description":"市市政园林局组织开展滑坡区域生态修复工作，恢复植被，防止水土流失。","resources":[]},{"step_id":36,"time":"","role":"区政府","action":"恢复重建","description":"受灾群众在蓝田县政府的协助下有序开展灾后重建工作，交通、电力、通讯抢修抢通，当地群众生活秩序基本恢复。","resources":[{"resource_type":"运输车辆","quantity":2},{"resource_type":"挖掘机","quantity":1}]},{"step_id":37,"time":"","role":"后勤保障和善后安置组","action":"善后处置","description":"后勤保障和善后安置组做好善后处置工作，妥善安置受灾群众，落实救助政策，帮助群众尽快恢复正常生活。","resources":[]},{"step_id":38,"time":"","role":"市应急局","action":"灾损评估","description":"市应急局组织开展灾损评估工作，全面核实灾害造成的人员伤亡、财产损失和基础设施损毁情况，为恢复重建提供依据。","resources":[]},{"step_id":39,"time":"","role":"应急指挥部","action":"响应终止","description":"蓝田县普化镇暴雨缓解，抢险救灾工作基本结束，经指挥部会商研判，宣布终止Ⅱ级应急响应，转入恢复重建阶段。","resources":[]}]}
